
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wb97x_d3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wb97x_d3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.429444216861727e+00, -3.362461953446961e+00, -3.268685216605459e+00, -3.138967297796851e+00, -2.962637387662863e+00, -2.728920381665798e+00, -2.430143691492629e+00, -2.066935109383719e+00, -1.653115097136308e+00, -1.217475148654975e+00, -8.078151827153084e-01, -4.998108347339701e-01, -4.217910969273986e-01, -3.264668801314122e-01, -2.069770888937676e-01, -9.390255773923609e-02, -3.239026825991767e-02, -3.440201960567770e-03, -7.758748278520781e-04, -1.741664237009887e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


